// tests/node/mesh-import-loader.test.ts — Tier 3 loader acceptance (PR12).
//
// The one-mesh GLBs that plastis3d_scene/mesh_import.py writes for STL, OBJ
// and PLY input (fixtures generated by tests/fixtures/make_mesh_import_glbs.py)
// must be accepted by three.js's GLTFLoader, with the geometry and the
// attributes the converter promises. Loader acceptance, not a glTF
// conformance claim.

import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import * as THREE from "three";
import { GLTFLoader } from "three/addons/loaders/GLTFLoader.js";
import { describe, expect, it } from "vitest";

async function load(name: string): Promise<THREE.Mesh> {
  const bytes = readFileSync(fileURLToPath(new URL(`../fixtures/${name}`, import.meta.url)));
  const copy = new Uint8Array(bytes.length);
  copy.set(bytes);
  const gltf = await new GLTFLoader().parseAsync(copy.buffer, "");
  const meshes: THREE.Mesh[] = [];
  gltf.scene.traverse((o) => {
    if ((o as THREE.Mesh).isMesh) meshes.push(o as THREE.Mesh);
  });
  expect(meshes).toHaveLength(1);
  return meshes[0];
}

function triangles(mesh: THREE.Mesh): number {
  const g = mesh.geometry;
  return (g.index ? g.index.count : g.attributes.position.count) / 3;
}

describe("converted OBJ, STL and PLY load in GLTFLoader", () => {
  for (const format of ["stl", "obj", "ply"]) {
    it(`${format}: one mesh, two triangles, 180 x 90 with no unit conversion`, async () => {
      const mesh = await load(`mesh-import-${format}.glb`);
      expect(triangles(mesh)).toBe(2);
      mesh.geometry.computeBoundingBox();
      const box = mesh.geometry.boundingBox as THREE.Box3;
      expect(box.min.toArray()).toEqual([0, 0, 0]);
      expect(box.max.toArray()).toEqual([180, 90, 0]);
    });
  }

  it("obj keeps normals and UVs; ply keeps vertex colours; stl has neither", async () => {
    const obj = await load("mesh-import-obj.glb");
    expect(obj.geometry.attributes.normal).toBeDefined();
    expect(obj.geometry.attributes.uv).toBeDefined();
    const ply = await load("mesh-import-ply.glb");
    expect(ply.geometry.attributes.color).toBeDefined();
    expect((ply.material as THREE.MeshStandardMaterial).vertexColors).toBe(true);
    const stl = await load("mesh-import-stl.glb");
    expect(stl.geometry.attributes.normal).toBeUndefined();
    expect((stl.material as THREE.MeshStandardMaterial).flatShading).toBe(true); // flat by the loader
    expect(stl.geometry.attributes.color).toBeUndefined();
  });
});
